type Equal<T, U> = [T] extends [U] ? ([U] extends [T] ? true : false) : false;

function assertType<T extends true>() {
  return true as T;
}

const nullPrefault = z.object({
  a: z.union([z.string(), z.null()]).prefault(() => null),
});

const undefinedPrefault = z.object({
  a: z.union([z.string(), z.undefined()]).prefault(() => undefined),
});

// Pass: This is right ✅
assertType<
  Equal<z.infer<typeof nullPrefault>, { a: string | null }>
>();

console.log("Parsed -->", nullPrefault.parse({}));
// Parsed  --> { a: null } ✅

// Should pass but doesn't: wrong ❌
assertType<
  Equal<
    z.infer<typeof undefinedPrefault>,
    { a: string | undefined }
  >
>();

type Debug = z.infer<typeof undefinedPrefault>;
//    ^? type Debug = { a: string } ❌

console.log("Parse -->", undefinedPrefault.parse({}));
// Parsed  --> { }  ❌
```


